      '<circle cx="9" cy="4" r="1.1" fill="currentColor"/>' +
      '<circle cx="9" cy="8" r="1.1" fill="currentColor"/>' +
      '<circle cx="9" cy="12" r="1.1" fill="currentColor"/></svg>';

    function refreshNums(ul) {
      qsa('li', ul).forEach(function (li, i) {
        var n = qs('.disc-num', li);
        if (n) n.textContent = String(i + 1);
      });
    }

    function makeSortable(ul) {
      var dragging = null;
      var ghost = null;
      var started = false;
      var startPt = null;
      var tolerance = 6;
      var suppressClick = false;

      ul.querySelectorAll('li').forEach(function (li) {
        var label = li.textContent;
        var num = document.createElement('span');
        num.className = 'disc-num';
        li.textContent = '';
        li.insertBefore(num, li.firstChild);
        var sp = document.createElement('span');
        sp.className = 'disc-label';
        sp.textContent = label;
        li.appendChild(sp);
        var h = document.createElement('span');
        h.className = 'disc-handle';
        h.innerHTML = HANDLE_SVG;
        li.appendChild(h);
      });
      refreshNums(ul);

      function getPoint(e) {
        if (e.touches && e.touches[0]) return { x: e.touches[0].clientX, y: e.touches[0].clientY };
        if (e.changedTouches && e.changedTouches[0]) return { x: e.changedTouches[0].clientX, y: e.changedTouches[0].clientY };
        return { x: e.clientX, y: e.clientY };
      }

      function hitLi(target) {
        var li = target;
        while (li && li !== ul && li.tagName !== 'LI') li = li.parentNode;
        return (li && li.tagName === 'LI' && ul.contains(li)) ? li : null;
      }

      function onDown(e) {
        var target = hitLi(e.target);
        if (!target) return;
        dragging = target;
        started = false;
        var p = getPoint(e);
        startPt = p;
        var ghostRect = target.getBoundingClientRect();
        ghost = { w: ghostRect.width, h: ghostRect.height, offX: 0, offY: 0 };
        ghost.el = target.cloneNode(true);
        ghost.el.classList.add('drag-ghost');
        ghost.el.style.position = 'fixed';
        ghost.el.style.margin = '0';
        ghost.el.style.left = ghostRect.left + 'px';
        ghost.el.style.top = ghostRect.top + 'px';
        ghost.el.style.width = ghostRect.width + 'px';
        ghost.el.style.zIndex = '999';
        ghost.el.style.pointerEvents = 'none';

        var onMove = function (ev) {
          var pt = getPoint(ev);
          if (!started) {
            if (Math.abs(pt.x - startPt.x) < tolerance && Math.abs(pt.y - startPt.y) < tolerance) return;
            started = true;
            ghost.offX = pt.x - ghostRect.left;
            ghost.offY = pt.y - ghostRect.top;
            target.classList.add('is-dragging');
            ul.classList.add('is-reordering');
            document.body.appendChild(ghost.el);
            if (ev.cancelable) ev.preventDefault();
          }
          if (ev.cancelable) ev.preventDefault();
          ghost.el.style.left = (pt.x - ghost.offX) + 'px';
          ghost.el.style.top = (pt.y - ghost.offY) + 'px';

          var list = qsa('li', ul).filter(function (x) { return x !== dragging; });
          var beforeEl = null;
          for (var i = 0; i < list.length; i++) {
            var r = list[i].getBoundingClientRect();
            if (pt.y < r.top + r.height / 2) { beforeEl = list[i]; break; }
          }
          qsa('li', ul).forEach(function (x) { x.classList.remove('is-over'); });
          if (beforeEl) {
            beforeEl.classList.add('is-over');
            ul.insertBefore(dragging, beforeEl);
          } else {
            var last = list[list.length - 1];
            if (last) { last.classList.add('is-over'); ul.insertBefore(dragging, last.nextSibling); }
          }
        };

        function onUp() {
          window.removeEventListener('pointermove', onMove, true);
          window.removeEventListener('pointerup', onUp, true);
          window.removeEventListener('pointercancel', onCancel, true);
          if (started) {
            setTimeout(function () { suppressClick = true; }, 0);
            setTimeout(function () { suppressClick = false; }, 300);
          }
          if (ghost && ghost.el && ghost.el.parentNode) ghost.el.parentNode.removeChild(ghost.el);
          ul.querySelectorAll('li').forEach(function (x) { x.classList.remove('is-dragging', 'is-over'); });
          ul.classList.remove('is-reordering');
          dragging = null;
          ghost = null;
          started = false;
          refreshNums(ul);
        }
        function onCancel() { onUp(); }

        window.addEventListener('pointermove', onMove, { passive: false, capture: true });
        window.addEventListener('pointerup', onUp, true);
        window.addEventListener('pointercancel', onCancel, true);

        e.preventDefault();
      }

      ul.addEventListener('pointerdown', onDown);
      ul.addEventListener('click', function (e) { if (suppressClick) { e.preventDefault(); e.stopPropagation(); } }, true);
    }

    qsa('.disc-list').forEach(makeSortable);

    // ---------------- scoring ----------------
    function collectPayload() {
      var payload = [];
      var lists = qsa('.disc-list', modal);
      lists.forEach(function (ul, li) {
        qsa('li', ul).forEach(function (x, idx) {
          payload.push({ list: li, pos: idx, type: x.getAttribute('data-type') });
        });
      });
      return payload;
    }

    function score(payload) {
      var maj = [], min = [];
      payload.forEach(function (x) {
        if (x.pos === 0) maj.push(x.type);
        if (x.pos === 3) min.push(x.type);
      });
      function cnt(arr, ch) { return arr.reduce(function (a, v) { return a + (v === ch ? 1 : 0); }, 0); }
      return {
        d: cnt(maj, 'd') - cnt(min, 'd'),
        i: cnt(maj, 'i') - cnt(min, 'i'),
        s: cnt(maj, 's') - cnt(min, 's'),
        c: cnt(maj, 'c') - cnt(min, 'c')
      };
    }

    // ---------------- results ----------------
    function maxAbs(res) {
      var m = Math.max.apply(null, [Math.abs(res.d), Math.abs(res.i), Math.abs(res.s), Math.abs(res.c)]);
      return m === 0 ? 1 : m;
    }

    function renderResults(res, bodyEl) {
      var max = maxAbs(res);
      var letters = [
        { k: 'd', L: 'D' }, { k: 'i', L: 'I' }, { k: 's', L: 'S' }, { k: 'c', L: 'C' }
      ];
      var sorted = letters.slice().sort(function (a, b) { return Math.abs(res[b.k]) - Math.abs(res[a.k]); });
      var top = sorted[0].L;

      var rows = letters.map(function (it) {
        var v = res[it.k];
        var pos = Math.max(0, v), neg = Math.max(0, -v);
        var posPct = Math.round(pos / max * 100);
        var negPct = Math.round(neg / max * 100);
        var sign = v > 0 ? '+' : (v < 0 ? '−' : '');
        return '<div class="res-row" style="color: var(--' + it.k + ');">' +
          '<div class="res-letter res-letter--' + it.k + '">' + it.L + '</div>' +
          '<div><div class="res-name">' + it.L + '</div></div>' +
          '<div class="res-desc">' + TYPE_LABELS[it.k] + '</div>' +
          '<div class="res-val">' + sign + Math.abs(v) + '</div>' +
          '<div class="res-bar"><span class="neg" data-w="' + negPct + '"></span><span class="pos" data-w="' + posPct + '"></span></div>' +
        '</div>';
      }).join('');

      var html =
        '<div class="res-head"><h2>Ваши результаты DISC</h2>' +
        '<p>Оценка считается по позициям характеристик: самый верхний элемент каждого списка даёт +1, самый нижний — −1.</p></div>' +
        '<div class="res-rows">' + rows + '</div>' +
        '<p class="res-note">Доминирующий тип по вашим ответам — <b>' + top + '</b>. ' +
        (TYPE_LABELS[lower(top)] || '') +
        '</p>' +
        '<div class="res-foot">' +
          '<button class="disc-btn disc-btn--ghost" type="button" data-disc-restart>Пройти ещё раз</button>' +
          '<button class="disc-btn disc-btn--primary" type="button" data-disc-close2>Закрыть</button>' +
        '</div>';
      bodyEl.insertAdjacentHTML('beforeend', '<div class="disc-results" id="discResults">' + html + '</div>');

      var wrap = qs('#discResults', bodyEl);
      qsa('.res-bar .pos, .res-bar .neg', wrap).forEach(function (el) {
        requestAnimationFrame(function () { el.style.width = el.getAttribute('data-w') + '%'; });
      });

      function lower(L) { return L.toLowerCase(); }

      qsa('[data-disc-close2]', wrap).forEach(function (b) {
        b.addEventListener('click', function (e) { e.preventDefault(); closeModal(); });
      });
      qsa('[data-disc-restart]', wrap).forEach(function (b) {
        b.addEventListener('click', function (e) { e.preventDefault(); resetTest(); });
      });
      resultsVisible = true;
    }

    function resetTest() {
      // restore original order of all lists
      var lists = qsa('.disc-list', modal);
      DATA.forEach(function (cards, si) {
        lists.forEach(function (ul, ci) {
          var idx = si * 3 + ci;
          if (ci > 2) return;
          var group = cards.slice(idx, idx + 4);
          // rebuild
          ul.querySelectorAll('li').forEach(function (li) { li.remove(); });
          group.forEach(function (g) {
            var li = document.createElement('li');
            li.className = 'disc-item';
            li.setAttribute('data-type', g.t);
            li.textContent = g.l;
            ul.appendChild(li);
          });
          // re-attach inner structure
          ul.querySelectorAll('li').forEach(function (li) {
            var label = li.textContent;
            var num = document.createElement('span'); num.className = 'disc-num';
            li.textContent = '';
            li.insertBefore(num, li.firstChild);
            var sp = document.createElement('span'); sp.className = 'disc-label'; sp.textContent = label;
            li.appendChild(sp);
            var h = document.createElement('span'); h.className = 'disc-handle'; h.innerHTML = HANDLE_SVG;
            li.appendChild(h);
          });
          refreshNums(ul);
        });
      });
      var resEl = qs('#discResults', modal);
      if (resEl) resEl.remove();
      resultsVisible = false;
      setStep(0);
      body.scrollTop = 0;
    }

    // ---------------- finish ----------------
    btnFinish.addEventListener('click', function () {
      var payload = collectPayload();
      var res = score(payload);
      renderResults(res, body);
      requestAnimationFrame(function () {
        var el = qs('#discResults', body);
        if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    });

    // ---------------- boot ----------------
    render();
    // open the test right away — it is the whole point of the page
    requestAnimationFrame(openModal);
  })();
  </script>
</body>
</html>
